pub fn is_palindrome(text: Vec<char>) -> bool {
    // Two-pointer approach: compare characters from both ends moving towards the center.
    let mut left = 0;
    // If text.len() is 0, saturating_sub(1) will still yield 0 and the loop won't run.
    let mut right = text.len().saturating_sub(1);

    while left < right {
        // Convert both characters to ASCII lowercase before comparing.
        let a = text[left].to_ascii_lowercase();
        let b = text[right].to_ascii_lowercase();

        if a != b {
            return false;
        }

        left += 1;
        right = right.saturating_sub(1);
    }

    true
}

