    #[test]
    fn test_single_char() {
        assert!(is_palindrome(vec!['a']));
        assert!(is_palindrome(vec!['Z']));
    }

    #[test]
    fn test_even_length() {
        assert!(is_palindrome(vec!['A', 'b', 'B', 'a']));
        assert!(!is_palindrome(vec!['A', 'b', 'c', 'a']));
    }

    #[test]
    fn test_odd_length() {
        assert!(is_palindrome(vec!['R', 'a', 'c', 'e', 'C', 'a', 'r']));
        assert!(!is_palindrome(vec!['R', 'a', 'c', 'e', 'c', 'a', 't']));
    }

    #[test]
